const T = { ...THEMES[0].p };
let THEME = THEMES[0];
function applyTheme(id) {
  const th = THEMES.find((x) => x.id === id) || THEMES[0];
  THEME = th;
  Object.assign(T, th.p);
  return th;
}

/* fluid sizing: one scale that holds together from a 360px phone to a 4K monitor */
const FS = (min, max, vw) => "clamp(" + min + "px," + (vw || 1.1) + "vw," + max + "px)";
/* each age of the world carries its own light. the whole interface shifts with the era you are living in. */
const ERA_SKIN = {
  warring:  { key: "#c1442f", key2: "#7a1f18", glow: "rgba(193,68,47,.20)",  label: "WARRING STATES", mark: "\u2694" },
  founding: { key: "#4e9e6a", key2: "#1d4a33", glow: "rgba(78,158,106,.18)", label: "THE FOUNDING",   mark: "\u26E9" },
  sannin:   { key: "#d9a441", key2: "#6d4d17", glow: "rgba(217,164,65,.18)", label: "THE SANNIN",     mark: "\u2618" },
  third:    { key: "#5b8fc9", key2: "#1f3c5c", glow: "rgba(91,143,201,.18)", label: "THE THIRD WAR",  mark: "\u2726" },
  naruto:   { key: "#e08a3c", key2: "#7a4415", glow: "rgba(224,138,60,.20)", label: "THE LEAF",       mark: "\u268A" },
  boruto:   { key: "#9b7fe0", key2: "#452f78", glow: "rgba(155,127,224,.18)",mark: "\u25C8", label: "THE NEW ERA" },
};
/* an era accent that is legible on the current theme — the founding green that reads
   on near-black is a smear on paper, so light themes get a darkened version */
const skinFor = (era) => {
  const base = ERA_SKIN[era] || ERA_SKIN.naruto;
  if (!THEME.light) return base;
  const dark = (hex, amt) => {
    const h = hex.replace("#", "");
    const c2 = [0, 2, 4].map((i) => Math.max(0, Math.round(parseInt(h.slice(i, i + 2), 16) * amt)));
    return "#" + c2.map((x) => x.toString(16).padStart(2, "0")).join("");
  };
  return { ...base, key: dark(base.key, 0.55), key2: dark(base.key2 || base.key, 0.5), glow: dark(base.key, 0.4) + "22" };
};
const skinOf = (c) => ERA_SKIN[c && c.era] || ERA_SKIN.naruto;
/* the shared UI pieces read the live era skin from here so every panel lights the same way */
let SKIN = ERA_SKIN.naruto;
const setSkin = (c) => { SKIN = skinFor(c && c.era); return SKIN; };
