function trainMult(c, reg) {
  let m = 1;
  if (c.perks.includes("weights")) m += 0.35;
  if (c.perks.includes("gravity")) m += 0.25;
  if (c.perks.includes("clonestudy")) m += 0.30;
  if (c.perks.includes("diet")) m += 0.20;
  if (reg.spec) m *= reg.spec === c.specialty ? 1.7 : 0.4;
  return m;
}
function trainGain(c, reg, k) {
  const iron = c.perks.includes("iron") && (k === "str" || k === "tai") ? 2 : 1;
  return Math.max(1, Math.round(reg.s[k] * trainMult(c, reg) * iron * (1 - c.stats[k] / 150)));
}

