function rollBounties(c) {
  const out = [];
  const pool = VILLAGES.filter((v) => villageExists(c, v.id));
  for (let i = 0; i < 4; i++) {
    const t = pick(BOUNTY_TIERS);
    const v = pool.length ? pick(pool) : pick(VILLAGES);
    out.push({ name: randName(Math.random() < 0.5 ? "m" : "f"), rank: t.r, key: t.key, from: pool.length ? v.name : "the " + v.land, pay: rr(t.pay[0], t.pay[1]), lvl: ENEMIES[t.key].lvl });
  }
  return out;
}





