ROGUE_MOVES.forEach((m) => {
  MOVES[m.name] = { name: m.name, tier: m.tier, kind: m.kind, nature: null, pow: m.pow, cost: m.cost, eff: m.eff || null };
  (JUTSU.rogue = JUTSU.rogue || []).push([m.name, m.tier]);
});

