/* ============================ MORE BLOOD ============================ */
/* bloodlines beyond the great clans — rarer, regional, and mostly feared locally */
const EXTRA_KG = [
  { n: "Shikotsumyaku", d: "Your skeleton is a weapon rack. You can pull a blade out of your own arm.", v: "kiri", nat: null, j: [["Dance of the Camellia", 3], ["Dance of the Willow", 4], ["Ten-Finger Drilling Bullets", 5]] },
  { n: "Ice Release", d: "Water and wind at once, and the mirrors that come with it.", v: "kiri", nat: "Ice Release", j: [["Ice Style: Demonic Mirrors", 4], ["Ice Style: Thousand Needles", 3], ["Ice Style: Black Dragon", 5]] },
  { n: "Boil Release", d: "Corrosive mist that goes through armour and the people inside it.", v: "kiri", nat: "Boil Release", j: [["Boil Style: Steam Ram", 4], ["Boil Style: Skilled Mist", 5]] },
  { n: "Explosion Release", d: "You can make anything you touch detonate, including things you did not mean to.", v: "iwa", nat: "Explosion Release", j: [["Explosion Style: Landmine Fist", 4], ["Explosion Style: Blast Barrage", 5]] },
  { n: "Dust Release", d: "Three natures at once. What it touches stops existing in any form.", v: "iwa", nat: "Dust Release", j: [["Dust Style: Detachment of the Primitive World", 6]] },
  { n: "Steel Release", d: "Skin that turns to iron on contact, and bones that do not break.", v: "iwa", nat: null, j: [["Steel Style: Iron Skin", 3], ["Steel Style: Hardening Fist", 4]] },
  { n: "Storm Release", d: "Lightning bent into beams that follow their target around corners.", v: "kumo", nat: "Storm Release", j: [["Storm Style: Laser Circus", 5], ["Storm Style: Guiding Light", 4]] },
  { n: "Scorch Release", d: "It boils the water out of a living body from across a field.", v: "suna", nat: "Scorch Release", j: [["Scorch Style: Incinerating Halo", 5]] },
  { n: "Crystal Release", d: "You grow crystal out of the air and everything inside it stops moving.", v: "konoha", nat: "Crystal Release", j: [["Crystal Style: Jade Crystal Prison", 5], ["Crystal Style: Crystal Needles", 3]] },
  { n: "Swift Release", d: "You are simply somewhere else. The eye does not follow it and neither does the Sharingan.", v: "konoha", nat: null, j: [["Swift Style: Shadowless Flight", 5]] },
  { n: "Lava Release", d: "Rock made liquid and thrown.", v: "kumo", nat: "Lava Release", j: [["Lava Style: Melting Apparition", 4], ["Lava Style: Quicklime Congealing", 5]] },
  { n: "Ranton Chains", d: "Chakra chains out of your own back, strong enough to hold a tailed beast still.", v: "uzu", nat: null, j: [["Adamantine Sealing Chains", 5], ["Chakra Chain Bind", 4]] },
];
EXTRA_KG.forEach((k) => {
  if (!JUTSU[k.n]) JUTSU[k.n] = [];
  k.j.forEach(([n2, t]) => {
    if (!MOVES[n2]) MOVES[n2] = { name: n2, tier: t, kind: t >= 5 ? "nin" : "nin", nature: k.nat || k.n, pow: 44 + t * 16, cost: 12 + t * 6, eff: t >= 5 ? "burn" : null };
    if (!JUTSU[k.n].some((x) => x[0] === n2)) JUTSU[k.n].push([n2, t]);
  });
  if (k.nat && !NC[k.nat]) NC[k.nat] = "#b47fe0";
  if (!NC[k.n]) NC[k.n] = "#b47fe0";
});
/* a rare chance of one of these waking up in anybody, weighted to the right country */
function rollExtraKG(c) {
  if (c.kg || c.myClan) return null;
  const local = EXTRA_KG.filter((k) => k.v === c.village);
  const pool = local.length && roll(70) ? local : EXTRA_KG;
  return pick(pool);
}

