        if (f.cost === "self") { c2.stats.cha = cl(c2.stats.cha - rr(3, 8)); P(L2, "Something of you went into learning it and did not come back out.", "b"); }
        if (f.cost === "health") { c2.health = cl(c2.health - rr(8, 18)); }
