            ln.current = { id: null, name: c.name, from: c.year, term: 999, player: true };
            c.rank = 6; c.rankName = kageOrdinal(ln) + " " + kageWordFor(c, c.village); c.standing = 100;
            if (c.anbu) { const cd = c.anbu.code; addTitle(c, TT(c, "anbuName") + " (retired)"); c.anbu = null; P(L, "You handed the mask back the same week. " + cd + " is retired — the seat and the mask cannot be worn by the same person.", "n"); }
            addTitle(c, c.rankName);
            initVillage(c, V.name, kageWordFor(c, c.village)); c.vil.gen = ln.past.length + 1;
            c.kages[c.village] = { named: null, name: c.name, title: c.rankName };
